contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 value) public {
        require(to != address(0));
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        bool reverted;
        if (balBefore >= value) {
            c.transfer(to, value);
        }
        if (balBefore >= value) {
            reverted = false;
            assert(
                c.balanceOf(address(this)) == balBefore - value &&
                c.balanceOf(to) == value &&
                c.totalSupply() == totalBefore
            );
        } else {
            try c.transfer(to, value) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        }
    }
    receive() external payable {}
}

